using FHeroes2.Assets.Maps;
using FHeroes2.Core.Io;

namespace FHeroes2.Assets.Tests;

/// <summary>
/// Covers <see cref="Mp2Map"/> and the tile / add-on structures, the port of the first half of
/// <c>World::loadMapMP2</c> and of <c>MP2::loadTile</c> / <c>MP2::loadAddon</c>. The synthetic maps
/// below are generated by <see cref="Mp2MapFileBuilder"/>; the last test runs against the real game
/// data and returns early when it is missing (see docs/MISC.md).
/// </summary>
public sealed class Mp2MapTests
{
    [Fact]
    public void Read_ParsesAnEmptyMap()
    {
        using TemporaryMapFile file = TemporaryMapFile.Create(new Mp2MapFileBuilder(36));

        Mp2Map map = Mp2Map.Read(file.FilePath);

        Assert.Equal(36, map.Width);
        Assert.Equal(36, map.Height);
        Assert.Equal(36 * 36, map.TileCount);
        Assert.Single(map.Addons); // index 0 is the "no add-on" placeholder
        Assert.Empty(map.Castles);
        Assert.Empty(map.CaptureObjects);
        Assert.Equal(0, map.ObeliskCount);
        Assert.Empty(map.InfoBlocks);
        Assert.Equal(100u, map.LastObjectUid);
        Assert.All(map.Tiles, tile => Assert.True(tile.IsEmpty));
    }

    [Fact]
    public void Read_ParsesTheTileFields()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.Tiles[10] = default(Mp2TileInfo) with
        {
            TerrainImageIndex = 0x1234,
            ObjectName1 = 5 << 2, // ICN type 5
            BottomIcnImageIndex = 7,
            Quantity1 = 0b1_1111, // layer 3, metadata bits
            Quantity2 = 0xFF,
            ObjectName2 = 35 << 2, // ICN type 35
            TopIcnImageIndex = 9,
            TerrainFlags = 0x1D,
            ObjectType = Mp2ObjectType.ActionHero,
            NextAddonIndex = 0,
            Level1ObjectUid = 0x11223344,
            Level2ObjectUid = 0x55667788,
        };

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);
        Mp2TileInfo tile = Mp2Map.Read(file.FilePath).Tiles[10];

        Assert.Equal(0x1234, tile.TerrainImageIndex);
        Assert.Equal(Mp2ObjectIcnType.Unused5, tile.GroundIcnType);
        Assert.Equal(Mp2ObjectIcnType.ObjnTown, tile.TopIcnType);
        Assert.Equal(3, tile.GroundLayer);
        Assert.Equal(7, tile.BottomIcnImageIndex);
        Assert.Equal(9, tile.TopIcnImageIndex);
        Assert.Equal(1, tile.TerrainShape);
        Assert.Equal(Mp2ObjectType.ActionHero, tile.ObjectType);
        Assert.Equal(0x11223344u, tile.Level1ObjectUid);
        Assert.Equal(0x55667788u, tile.Level2ObjectUid);
        Assert.True(tile.HasGroundObject);
        Assert.True(tile.HasTopObject);

        // ((0xFF << 8) + 0x1F) >> 3
        Assert.Equal(0x1FE3u, tile.Metadata);
    }

    [Fact]
    public void Read_FollowsTheAddonChain()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.Tiles[5] = default(Mp2TileInfo) with { NextAddonIndex = 1 };
        builder.Addons.Add(default(Mp2AddonInfo) with
        {
            NextAddonIndex = 2,
            ObjectNameN1 = 40 << 2, // ICN type 40
            BottomIcnImageIndex = 3,
            QuantityN = 0b1_1111,
            ObjectNameN2 = 12 << 2, // ICN type 12
            TopIcnImageIndex = 4,
            Level1ObjectUid = 42,
            Level2ObjectUid = 43,
        });
        builder.Addons.Add(default(Mp2AddonInfo) with { NextAddonIndex = 0, ObjectNameN1 = 8 });

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);
        Mp2Map map = Mp2Map.Read(file.FilePath);

        Assert.Equal([1, 2], map.EnumerateAddonChain(map.Tiles[5]));

        Mp2AddonInfo addon = map.Addons[1];
        Assert.Equal(Mp2ObjectIcnType.ObjnWat2, addon.GroundIcnType);
        Assert.Equal(Mp2ObjectIcnType.Mons32, addon.TopIcnType);
        Assert.Equal(3, addon.GroundLayer);
        Assert.Equal(42u, addon.Level1ObjectUid);
        Assert.Equal(Mp2ObjectIcnType.Unused2, map.Addons[2].GroundIcnType);
    }

    [Fact]
    public void EnumerateAddonChain_StopsOnALoop()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.Tiles[0] = default(Mp2TileInfo) with { NextAddonIndex = 1 };
        builder.Addons.Add(default(Mp2AddonInfo) with { NextAddonIndex = 2 });
        builder.Addons.Add(default(Mp2AddonInfo) with { NextAddonIndex = 1 });

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);
        Mp2Map map = Mp2Map.Read(file.FilePath);

        Assert.Equal(map.Addons.Count, map.EnumerateAddonChain(map.Tiles[0]).Count());
    }

    [Fact]
    public void EnumerateAddonChain_StopsOnAnOutOfRangeIndex()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.Tiles[0] = default(Mp2TileInfo) with { NextAddonIndex = 99 };

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);
        Mp2Map map = Mp2Map.Read(file.FilePath);

        Assert.Empty(map.EnumerateAddonChain(map.Tiles[0]));
    }

    [Fact]
    public void Read_ConvertsTheThatchedHutIntoAPeasantHut()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.Tiles[0] = default(Mp2TileInfo) with { ObjectType = (Mp2ObjectType)65 };
        builder.Tiles[1] = default(Mp2TileInfo) with { ObjectType = (Mp2ObjectType)193 };

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);
        Mp2Map map = Mp2Map.Read(file.FilePath);

        Assert.Equal(Mp2ObjectType.PeasantHut, map.Tiles[0].ObjectType);
        Assert.Equal(Mp2ObjectType.ActionPeasantHut, map.Tiles[1].ObjectType);
    }

    [Fact]
    public void Read_ParsesTheCastleTable()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.Castles.Add((10, 20, 0x00)); // knight town
        builder.Castles.Add((30, 40, 0x81)); // barbarian castle
        builder.Castles.Add((5, 6, 0x86)); // castle of an unknown race

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);
        Mp2Map map = Mp2Map.Read(file.FilePath);

        Assert.Equal(3, map.Castles.Count);

        Assert.Equal(10, map.Castles[0].X);
        Assert.Equal(20, map.Castles[0].Y);
        Assert.Equal(MapRace.Knight, map.Castles[0].Race);
        Assert.False(map.Castles[0].HasFort);

        Assert.Equal(MapRace.Barbarian, map.Castles[1].Race);
        Assert.True(map.Castles[1].HasFort);

        Assert.Equal(MapRace.None, map.Castles[2].Race);
        Assert.True(map.Castles[2].HasFort);
    }

    [Fact]
    public void Read_ParsesTheCaptureObjectTable()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.CaptureObjects.Add((1, 2, 0x00)); // sawmill
        builder.CaptureObjects.Add((3, 4, 0x04)); // any mine
        builder.CaptureObjects.Add((5, 6, 0x64)); // lighthouse
        builder.CaptureObjects.Add((7, 8, 0x65)); // dragon city
        builder.CaptureObjects.Add((9, 10, 0x67)); // abandoned mine
        builder.CaptureObjects.Add((11, 12, 0x99)); // unknown

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);
        Mp2Map map = Mp2Map.Read(file.FilePath);

        Assert.Equal(
            [
                Mp2ObjectType.Sawmill,
                Mp2ObjectType.Mine,
                Mp2ObjectType.Lighthouse,
                Mp2ObjectType.DragonCity,
                Mp2ObjectType.AbandonedMine,
                Mp2ObjectType.None,
            ],
            map.CaptureObjects.Select(entry => entry.ObjectType));
        Assert.Equal(0x04, map.CaptureObjects[1].RawType);
    }

    [Fact]
    public void Read_ParsesTheInformationBlocks()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.InfoBlocks.Add([1, 2, 3]);
        builder.InfoBlocks.Add([9, 8, 7, 6]);
        builder.ObeliskCount = 3;
        builder.LastObjectUid = 4242;

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);
        Mp2Map map = Mp2Map.Read(file.FilePath);

        Assert.Equal(3, map.ObeliskCount);
        Assert.Equal(4242u, map.LastObjectUid);
        Assert.Equal(2, map.InfoBlocks.Count);
        Assert.Equal(0, map.InfoBlocks[0].Index);
        Assert.Equal(1, map.InfoBlocks[0].ObjectId);
        Assert.Equal([1, 2, 3], map.InfoBlocks[0].Data);
        Assert.Equal(2, map.InfoBlocks[1].ObjectId);
        Assert.Equal([9, 8, 7, 6], map.InfoBlocks[1].Data);
    }

    [Fact]
    public void Read_AcceptsAnEmptyInformationBlock()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.InfoBlocks.Add([1]);
        builder.InfoBlocks.Add([]);
        builder.InfoBlocks.Add([2]);

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);

        // A zero sized block is skipped, exactly like the reference implementation does.
        Assert.Equal(2, Mp2Map.Read(file.FilePath).InfoBlocks.Count);
    }

    [Fact]
    public void Read_RejectsAnUnsupportedMapSize()
    {
        using TemporaryMapFile file = TemporaryMapFile.Create(new Mp2MapFileBuilder(50));

        Assert.Throws<BinaryFormatException>(() => Mp2Map.Read(file.FilePath));
    }

    [Fact]
    public void Read_RejectsATruncatedTileArea()
    {
        Mp2MapFileBuilder builder = new(36);
        byte[] content = builder.ToArray();

        using TemporaryMapFile file = TemporaryMapFile.Create(new byte[content.Length / 2]);

        Assert.Throws<BinaryFormatException>(() => Mp2Map.Read(file.FilePath));
    }

    [Fact]
    public void Read_RejectsPriceOfLoyaltyObjectsOnlyWhenAsked()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.Tiles[0] = default(Mp2TileInfo) with { ObjectType = Mp2ObjectType.Barrier };

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);

        Assert.Throws<BinaryFormatException>(() => Mp2Map.Read(file.FilePath, rejectPriceOfLoyaltyObjects: true));
        Assert.Equal(Mp2ObjectType.Barrier, Mp2Map.Read(file.FilePath).Tiles[0].ObjectType);
    }

    [Fact]
    public void TryRead_ReturnsFalseForATruncatedFile()
    {
        using TemporaryMapFile file = TemporaryMapFile.Create(new byte[64]);

        Assert.False(Mp2Map.TryRead(file.FilePath, out Mp2Map? map));
        Assert.Null(map);
    }

    [Fact]
    public void Tile_RejectsPointsOutsideTheMap()
    {
        using TemporaryMapFile file = TemporaryMapFile.Create(new Mp2MapFileBuilder(36));
        Mp2Map map = Mp2Map.Read(file.FilePath);

        Assert.Throws<ArgumentOutOfRangeException>(() => map.Tile(36, 0));
        Assert.Throws<ArgumentOutOfRangeException>(() => map.Tile(0, -1));
        Assert.Equal(map.Tiles[36], map.Tile(0, 1));
    }

    [Fact]
    public void GetSummary_DescribesTheMap()
    {
        Mp2MapFileBuilder builder = new(36);
        builder.Tiles[0] = default(Mp2TileInfo) with { ObjectName1 = 4 };

        using TemporaryMapFile file = TemporaryMapFile.Create(builder);
        string summary = Mp2Map.Read(file.FilePath).GetSummary();

        Assert.Contains("Builder Map", summary, StringComparison.Ordinal);
        Assert.Contains("1296 tiles", summary, StringComparison.Ordinal);
    }

    [Fact]
    public void Read_ParsesTheMapsOfTheRealGameData()
    {
        string? dataDirectory = GameData.ResolveDataDirectory();
        if (dataDirectory is null)
        {
            return;
        }

        string? mapFile = MapCatalog.FindFiles(MapCatalog.FindDirectories([dataDirectory]))
            .FirstOrDefault(path => Path.GetFileName(path).Equals("Beltway.mp2", StringComparison.OrdinalIgnoreCase));

        if (mapFile is null)
        {
            return;
        }

        Mp2Map map = Mp2Map.Read(mapFile);

        Assert.Equal(72, map.Width);
        Assert.Equal(72 * 72, map.TileCount);
        Assert.True(map.Addons.Count > 1, "The map has no add-ons at all.");
        Assert.True(map.Castles.Count > 0, "The map has no castles.");
        Assert.True(map.CaptureObjects.Count > 0, "The map has no capturable objects.");
        Assert.True(map.LastObjectUid > 0, "The object UID counter is zero.");

        // Every add-on reference must stay inside the add-on array, otherwise the file is corrupt.
        Assert.All(map.Tiles, tile => Assert.True(tile.NextAddonIndex < map.Addons.Count));
        Assert.All(map.Castles, castle => Assert.InRange(castle.X, 0, map.Width - 1));
    }
}
